from functools import cached_property

class Report:
    @cached_property
    def summary(self) -> Summary:
        return build_summary(self.rows)          # once per instance

    def add_row(self, row) -> None:
        self.rows.append(row)
        self.__dict__.pop("summary", None)       # invalidate
